/bin/zsh -lc "python3 -c 'import json
x=json.load(open(\"input.json\"))
adj={}
for e in x[\"edges\"]: adj.setdefault(e[\"source\"],[]).append(e)
paths={}
def visit(v,t,b,seen,ids,deps,energy):
    if v==\"T\":
        candidate=(t,energy,tuple(ids),tuple(deps))
        key=tuple(ids)
        if key not in paths or candidate<paths[key]: paths[key]=candidate
        return
    if v in x[\"recharge\"]: b=x[\"capacity\"]
    for e in adj.get(v,[]):
        if e[\"target\"] in seen or e[\"energy\"]>b: continue
        for d in range(max(t,e[\"open\"]),min(e[\"close\"]-1,x[\"deadline\"]-e[\"duration\"])+1):
            visit(e[\"target\"],d+e[\"duration\"],b-e[\"energy\"],seen|{e[\"target\"]},ids+[e[\"id\"]],deps+[d],energy+e[\"energy\"])
visit(\"S\",0,x[\"capacity\"],{\"S\"},[],[],0)
for key in sorted(paths): print(paths[key])
best=min(paths.values())
print(json.dumps(dict(selected_edges=best[2],departures=best[3],arrival=best[0],energy_consumed=best[1],feasible_path_count=len(paths))))'"

